def VTask.banana : {α : Type u_1} → {β : Type u_2} → (u v : α) → (edgeSet : Set β) → Graph α β :=
  fun {α} {β} u v edgeSet =>
    {
      adj := fun x y => (∃ (e : β), e ∈ edgeSet ∧ (x = u ∧ y = v ∨ x = v ∧ y = u))
      edge := fun e => (u, v)
      edges := fun x => {e : β | e ∈ edgeSet ∧ (x = u ∨ x = v)}
      edgesAt := fun x y => {e : β | e ∈ edgeSet ∧ (x = u ∧ y = v ∨ x = v ∧ y = u)}
      isLoop := fun e => (u = v)
      isNonloop := fun e => (u ≠ v)
      loopsAt := if u = v then {e : β | e ∈ edgeSet} else ∅
      nonloopsAt := if u = v then ∅ else {e : β | e ∈ edgeSet}
      neighbors := fun x => if x = u then {v} else if x = v then {u} else ∅
      neighborsOf := fun x => if x = u then {v} else if x = v then {u} else ∅
      vertices := {u, v}
    }
